/*
 * nb_scene_menu.c — Scene select menu (scene gallery).
 *
 * Grid menu over the build-time scene table (core/engine/nb_scene_menu.h,
 * generated by tools/naiz_build/scene_menu.py from scenes opting in via
 * sceneconf(){title, normal, onlist}).
 *
 * Structure mirrors nb_cggallery.c: menu-layer composite drawing, reserved
 * palette slots, paging/back chrome from nb_internal.h, and the same exit
 * contract (menu_finish + parent scene switch).  Differences:
 *   - no fullscreen preview: activating a cell starts that scene;
 *   - cells always show a focus border (white idle, yellow selected);
 *   - thumb_id 0 falls back to the title's first letter (uppercase);
 *   - locked scenes are hidden, not greyed out (CG-gallery parity), and a
 *     scene started here returns to the gallery on scene(end).
 *
 * Layout: 3 cols x 2 rows, cell 180x130, thumbnail 160x100 at (+10,+4),
 * title baseline at y+108.  Geometry is mirrored by THUMB_W/GRID_* in
 * scene_menu.py and guarded by tools/tests/test_scene_menu.py.
 */
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include "render.h"
#include "image.h"
#include "scene_layers.h"
#include "menu_layer.h"
#include "hal.h"
#include "nb.h"
#include "nb_internal.h"
#include "nb_commands.h"
#include "ui.h"
#include "debug.h"
#include "tr.h"
#include "frame.h"
#include "input_boundary.h"
#include "save.h"
#include "nb_scene_menu.h"

#define SCM_COLS        3
#define SCM_ROWS        2
#define SCM_CELLS       (SCM_COLS * SCM_ROWS)
#define SCM_ORIGIN_X    46
#define SCM_ORIGIN_Y    40
#define SCM_CELL_W      180
#define SCM_CELL_H      130
#define SCM_STEP_X      184     /* cell 180 + 4 gap */
#define SCM_STEP_Y      134     /* cell 130 + 4 gap */
#define SCM_THUMB_W     160
#define SCM_THUMB_H     100
#define SCM_THUMB_OX    10      /* (180 - 160) / 2 */
#define SCM_THUMB_OY    4
#define SCM_TITLE_OY    108     /* thumb ends at 104, 4px gap */
#define SCM_ICON_GLYPH_H 64     /* draw_title_large(scale 4) glyph height */

/* Origin 40 + one 134 step + cell 130; kept numeric so the guard test can
 * read it without evaluating arithmetic. */
#define SCM_GRID_BOTTOM 304
#define SCM_LAST_CELL_IDX (SCM_CELLS - 1)

#define SCM_ARROWS_Y    318
#define SCM_COUNT_Y     330
#define SCM_BACK_Y      352

#define SCM_FILL_ICON   255     /* letter-icon backing plate (blue) */
#define SCM_FG          MENU_PAL_WHITE
#define SCM_FG_SEL      MENU_PAL_YELLOW

/* Saved value of palette slot 255 (icon plate) restored on exit. */
static uint8_t scm_blue_save[3];

/* Indexes into scene_menu_entries whose scene has been unlocked.  The
 * generated table is the full onlist set; the grid only pages over this
 * subset, so unplayed scenes are absent rather than shown locked. */
static unsigned short scm_visible[SCENE_MENU_COUNT > 0 ? SCENE_MENU_COUNT : 1];
static int scm_visible_count;

static void scm_build_visible(void)
{
    int i;

    scm_visible_count = 0;
    for (i = 0; i < SCENE_MENU_COUNT; i++) {
        if (sys_save_is_scene_unlocked(scene_menu_entries[i].unlock_id))
            scm_visible[scm_visible_count++] = (unsigned short)i;
    }
}

static void scm_palette_save(void)
{
    hal_read_palette(SCM_FILL_ICON, &scm_blue_save[0], &scm_blue_save[1],
                     &scm_blue_save[2]);
    hal_set_palette(SCM_FILL_ICON, 0x00, 0x00, 0xFF);
}

static void scm_palette_restore(void)
{
    hal_set_palette(SCM_FILL_ICON, scm_blue_save[0], scm_blue_save[1],
                    scm_blue_save[2]);
}

static void scm_cell_xy(int i, int *px, int *py)
{
    *px = SCM_ORIGIN_X + (i % SCM_COLS) * SCM_STEP_X;
    *py = SCM_ORIGIN_Y + (i / SCM_COLS) * SCM_STEP_Y;
}

/* Draw one grid cell: thumbnail (or letter icon) + centered title + border.
 * abs_idx is an index into scm_visible, mapped to the full table here. */
static void scm_draw_cell(int abs_idx, int x, int y, int is_sel)
{
    const SceneMenuEntry *entry = &scene_menu_entries[scm_visible[abs_idx]];
    int tx = x + SCM_THUMB_OX, ty = y + SCM_THUMB_OY;
    const char *title;
    int tw;

    if (entry->thumb_id != 0) {
        MagImage *thumb = image_load((unsigned short)entry->thumb_id);
        if (thumb) {
            menu_layer_blit_sprite(thumb, tx, ty, PAL_NO_TRANSPARENCY);
            mag_release(thumb);
        } else {
            NB_DEBUG("[SCENEMENU] thumb load failed scene=%s id=%u\r\n",
                     entry->scene, (unsigned)entry->thumb_id);
            fill_rect(tx, ty, SCM_THUMB_W, SCM_THUMB_H, SCM_FILL_ICON);
        }
    } else {
        char letter[2];
        int lw;
        fill_rect(tx, ty, SCM_THUMB_W, SCM_THUMB_H, SCM_FILL_ICON);
        letter[0] = (char)toupper((unsigned char)entry->title[0]);
        letter[1] = '\0';
        lw = text_title_width(letter, 4);
        draw_title_large(letter, tx + (SCM_THUMB_W - lw) / 2,
                         ty + (SCM_THUMB_H - SCM_ICON_GLYPH_H) / 2,
                         4, SCM_FG);
    }

    title = tr(entry->title);
    tw = text_width(title, 0);
    if (tw > SCM_CELL_W - 8) {
        /* draw_text clips silently; clamp the centering origin instead. */
        tw = SCM_CELL_W - 8;
    }
    draw_text(title, 0, x + (SCM_CELL_W - tw) / 2, y + SCM_TITLE_OY,
              x + SCM_CELL_W - 4, y + SCM_TITLE_OY + 16, 0,
              is_sel ? SCM_FG_SEL : SCM_FG);
    draw_rect(x, y, SCM_CELL_W, SCM_CELL_H, is_sel ? 2 : 1,
              is_sel ? SCM_FG_SEL : SCM_FG);
}

/* Full redraw: title band + grid band + footer band (each erased to base). */
static void scm_draw_grid(int page, int sel, int focus_on_back)
{
    int total_pages = menu_pagecount(scm_visible_count, SCM_CELLS);
    int page_start = page * SCM_CELLS;
    int tw;
    int i;

    menu_layer_begin_draw();

    vblank_wait();
    menu_layer_erase_to_base(0, 0, LAYER_SCREEN_W, SCM_ORIGIN_Y);
    menu_layer_erase_to_base(0, SCM_ORIGIN_Y, LAYER_SCREEN_W,
                             SCM_GRID_BOTTOM - SCM_ORIGIN_Y);
    menu_layer_erase_to_base(0, SCM_GRID_BOTTOM, LAYER_SCREEN_W,
                             LAYER_SCREEN_H - SCM_GRID_BOTTOM);

    tw = text_title_width(tr("SCENE GALLERY"), 3);
    draw_title_large(tr("SCENE GALLERY"), (LAYER_SCREEN_W - tw) / 2, 4, 3, SCM_FG);

    for (i = 0; i < SCM_CELLS; i++) {
        int abs_idx = page_start + i;
        int x, y;
        if (abs_idx >= scm_visible_count) break;
        scm_cell_xy(i, &x, &y);
        scm_draw_cell(abs_idx, x, y, (i == sel) && !focus_on_back);
    }

    menu_back_draw(SCM_BACK_Y, focus_on_back, 1, SCM_FG);
    menu_pagenav_draw(SCM_ARROWS_Y, SCM_COUNT_Y, SCM_FG, page, total_pages);

    menu_layer_commit();
    menu_layer_blit();
}

/* Incremental redraw of the cells whose focus changed, plus the Back button. */
static void scm_draw_cells_range(int page, int from_sel, int to_sel,
                                 int focus_on_back)
{
    menu_layer_begin_draw();

    /* One button, so a full redraw with the current focus is cheapest and
     * keeps the highlighted state correct in both directions. */
    menu_back_draw(SCM_BACK_Y, focus_on_back, 1, SCM_FG);

    if (page * SCM_CELLS + from_sel < scm_visible_count) {
        int x, y;
        scm_cell_xy(from_sel, &x, &y);
        menu_layer_erase_to_base(x, y, SCM_CELL_W, SCM_CELL_H);
        scm_draw_cell(page * SCM_CELLS + from_sel, x, y, 0);
    }
    if (!focus_on_back && page * SCM_CELLS + to_sel < scm_visible_count) {
        int x, y;
        scm_cell_xy(to_sel, &x, &y);
        menu_layer_erase_to_base(x, y, SCM_CELL_W, SCM_CELL_H);
        scm_draw_cell(page * SCM_CELLS + to_sel, x, y, 1);
    }

    menu_layer_commit();
    menu_layer_blit();
}

/* Return to the menu-parent scene (set by specialmenu), else the main menu. */
static void scm_return_home(void)
{
    const char *ret = nb_get_menu_return();
    scene_switch(ret[0] != '\0' ? ret : "mainmenu.nb", SCENE_SWITCH_MENU);
}

/* Empty menu: explain and wait for any dismiss input (gallery parity).
 * msg is the English i18n key; tr() resolves it for the runtime language. */
static void scm_empty(const char *msg)
{
    input_drain_boundary();
    hal_mouse_erase_cursor();
    draw_text(tr(msg), 0, 200, 190, 440, 210, 1, SCM_FG);
    hal_mouse_draw_cursor_force();
    for (;;) {
        engine_frame_pump();
        hal_kbd_update();
        hal_mouse_update();
        if (hal_kbd_is_down(KC_ESC) || hal_kbd_is_down(KC_SPACE) ||
            hal_kbd_is_down(KC_ENTER) || hal_kbd_is_down(KC_XFER) ||
            hal_mouse_was_clicked(HAL_MOUSE_LBUTTON))
            break;
        hal_mouse_draw_cursor();
    }
    hal_mouse_flush();
    scm_return_home();
}

/* cmd_scenesmenu — scene select grid (bridging script scenes.nb ends). */
void cmd_scenesmenu(int argc, const char **argv, const char *cmd_name)
{
    int running = 1, total_pages, page = 0, sel = 0, focus_on_back = 0;
    int chosen = -1;

    (void)argc; (void)argv; (void)cmd_name;

    if (SCENE_MENU_COUNT == 0) {
        NB_DEBUG("scenesmenu: SCENE_MENU_COUNT=0, empty scene menu\r\n");
        scm_empty("No scenes available.");
        return;
    }

    scm_build_visible();
    NB_DEBUG("scenesmenu: %d/%d scenes unlocked\r\n",
             scm_visible_count, SCENE_MENU_COUNT);
    if (scm_visible_count == 0) {
        scm_empty("Play the story to unlock scenes.");
        return;
    }

    total_pages = menu_pagecount(scm_visible_count, SCM_CELLS);

    input_drain_boundary();
    hal_mouse_erase_cursor();
    menu_save_item_palette();
    scm_palette_save();
    if (menu_layer_open(0, 0, LAYER_SCREEN_W, LAYER_SCREEN_H, 0) != 0) {
        NB_DEBUG("[SCENEMENU] layer open failed\r\n");
    }
    scm_draw_grid(page, sel, focus_on_back);
    hal_mouse_set_pos(LAYER_SCREEN_W / 2, LAYER_SCREEN_H / 2);
    hal_mouse_draw_cursor_force();

    while (running) {
        int prev_sel = sel, prev_fb = focus_on_back;
        int abs_sel = page * SCM_CELLS + sel;

        engine_frame_pump();
        hal_kbd_update();

        if (focus_on_back) {
            if (hal_kbd_is_down(KC_UP)) {
                int last_idx = scm_visible_count - page * SCM_CELLS - 1;
                focus_on_back = 0;
                sel = (last_idx < SCM_LAST_CELL_IDX) ? last_idx : SCM_LAST_CELL_IDX;
            } else if (hal_kbd_is_down(KC_ENTER) || hal_kbd_is_down(KC_SPACE) ||
                       hal_kbd_is_down(KC_XFER)) {
                running = 0;
                continue;
            }
        } else {
            int last_idx = scm_visible_count - page * SCM_CELLS - 1;

            if (hal_kbd_is_down(KC_UP) && sel / SCM_COLS > 0) {
                sel -= SCM_COLS;
            } else if (hal_kbd_is_down(KC_DOWN)) {
                if (sel + SCM_COLS > last_idx)
                    focus_on_back = 1;
                else
                    sel += SCM_COLS;
            } else if (hal_kbd_is_down(KC_LEFT)) {
                if (sel % SCM_COLS > 0) {
                    sel--;
                } else if (page > 0) {
                    page--; sel = 0;
                    scm_draw_grid(page, sel, focus_on_back);
                    hal_mouse_draw_cursor_force();
                    continue;
                }
            } else if (hal_kbd_is_down(KC_RIGHT)) {
                if (sel % SCM_COLS < SCM_COLS - 1 &&
                    page * SCM_CELLS + sel + 1 < scm_visible_count) {
                    sel++;
                } else if (page < total_pages - 1) {
                    page++; sel = 0;
                    scm_draw_grid(page, sel, focus_on_back);
                    hal_mouse_draw_cursor_force();
                    continue;
                }
            } else if (hal_kbd_is_down(KC_ENTER) || hal_kbd_is_down(KC_SPACE) ||
                       hal_kbd_is_down(KC_XFER)) {
                chosen = abs_sel;
                running = 0;
                continue;
            }
        }
        if (hal_kbd_is_down(KC_ESC)) { running = 0; continue; }

        hal_mouse_update();
        if (hal_mouse_was_clicked(HAL_MOUSE_LBUTTON)) {
            int mx = hal_mouse_get_x(), my = hal_mouse_get_y(), i;

            if (menu_back_hit(SCM_BACK_Y, mx, my)) { running = 0; continue; }
            if (menu_page_hit(SCM_ARROWS_Y, mx, my) == 1 && page > 0) {
                page--; sel = 0;
                scm_draw_grid(page, sel, focus_on_back);
                hal_mouse_draw_cursor_force();
                continue;
            }
            if (menu_page_hit(SCM_ARROWS_Y, mx, my) == 2 && page < total_pages - 1) {
                page++; sel = 0;
                scm_draw_grid(page, sel, focus_on_back);
                hal_mouse_draw_cursor_force();
                continue;
            }
            for (i = 0; i < SCM_CELLS; i++) {
                int gx, gy;
                if (page * SCM_CELLS + i >= scm_visible_count) break;
                scm_cell_xy(i, &gx, &gy);
                if (mx >= gx && mx < gx + SCM_CELL_W &&
                    my >= gy && my < gy + SCM_CELL_H) {
                    chosen = page * SCM_CELLS + i;
                    running = 0;
                    break;
                }
            }
        }

        if (running && (sel != prev_sel || focus_on_back != prev_fb))
            scm_draw_cells_range(page, prev_sel, sel, focus_on_back);

        hal_mouse_draw_cursor();
    }

    menu_finish();
    scm_palette_restore();
    if (chosen >= 0) {
        /* GALLERY arms playback mode: scene(end) then returns to scenes.nb
         * instead of the main menu (devdoc 209). */
        scene_switch(scene_menu_entries[scm_visible[chosen]].scene,
                     SCENE_SWITCH_GALLERY);
    } else {
        scm_return_home();
    }
}
